<?php require __DIR__.'/../app/bootstrap.php';$u=role(['admin','kasir','teknisi']);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("INSERT INTO parts(sku,name,category,stock,min_stock,buy_price,sell_price)VALUES(?,?,?,?,?,?,?)");$s->execute([trim($_POST['sku']),trim($_POST['name']),trim($_POST['category']),max(0,(int)$_POST['stock']),max(0,(int)$_POST['min']),max(0,(float)$_POST['buy']),max(0,(float)$_POST['sell'])]);audit($pdo,$u['id'],'part_create',$_POST['sku']);header('Location:parts.php');exit;}$rows=$pdo->query("SELECT * FROM parts ORDER BY name")->fetchAll();?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Sparepart</title><style>body{font:14px Arial;background:#f5f7fb;margin:0}.top{background:#111827;color:#fff;padding:16px 24px}.top a{color:#fff;margin-left:14px}.wrap{max-width:1100px;margin:25px auto;padding:0 15px}.card{background:#fff;padding:18px;border-radius:12px;margin-bottom:15px}.form{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.form input{padding:9px}.btn{background:#2563eb;color:#fff;border:0;padding:10px;border-radius:7px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}@media(max-width:700px){.form{grid-template-columns:1fr}}</style><div class=top><b>🔧 ServisPro</b><a href=index.php>Dashboard</a><a href=tickets.php>Tiket</a><a href=customers.php>Pelanggan</a><a href=payments.php>Pembayaran</a><a href=logout.php>Keluar</a></div><div class=wrap><h2>Sparepart</h2><div class=card><form method=post class=form><input type=hidden name=csrf value="<?=e(csrf())?>"><input name=sku placeholder=SKU required><input name=name placeholder=Nama required><input name=category placeholder=Kategori><input name=stock type=number min=0 placeholder=Stok><input name=min type=number min=0 placeholder=Minimum><input name=buy type=number min=0 placeholder="Harga beli"><input name=sell type=number min=0 placeholder="Harga 